/**
 * A listing source (tag, user, pseud, bookmarks, collection, series) is queued for the
 * daemon, which fetches page 1 and creates it (202; poll the Location). A single work is
 * added at once (201). An existing source is 409 `already-exists`, with the source as
 * Location. Invalid members are one 422 `validation-error` listing each by `pointer`; a
 * URL that is not a supported AO3 source page gets its reason's hint at `/url`. `confirm`
 * is accepted only on the admin socket (a validation error at `/confirm` on the public
 * listener), so a source over `sources.auto_confirm_max` added publicly waits for
 * `source confirm`. Rate limited per client by `api.rate.source_add_per_hour`.
 * @summary Add a source.
 */
export const addSource = async (sourceAddRequest: SourceAddRequest, options?: Parameters<typeof apiFetch>[1]): Promise<addSourceResponse> => {

  return apiFetch<addSourceResponse>(getAddSourceUrl(),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(sourceAddRequest)
  }
);}



