/**
 * Its next update poll is due now and its failed work fetches are queued again. With
 * `full`, the whole listing is re-walked (a rescan) and a parse-failure block is cleared.
 * Only active and done_backfill sources can be refreshed; any other state is 409
 * `state-conflict`. The running daemon picks the change up within seconds.
 * @summary Make a source catch up now instead of waiting.
 */
export const refreshSource = async (id: number,
    sourceRefreshRequest: SourceRefreshRequest, options?: Parameters<typeof apiFetch>[1]): Promise<refreshSourceResponse> => {

  return apiFetch<refreshSourceResponse>(getRefreshSourceUrl(id),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(sourceRefreshRequest)
  }
);}



